// Get last processed AUR ID
$last_aur_nid = variable_get('last_aur', 1);
$last_aur_nid_orig = $last_aur_nid;

// Find new last AUR
$result = db_query("SELECT MAX(nid) FROM {node} WHERE status = 1 AND type = 'asset_usage_record'");
$new_max_aur = $result->fetchField();
if ($new_max_aur) {
    variable_set('last_aur', $new_max_aur);
}

// Single query to get all data needed
$result = db_query("
    SELECT 
        nrp.nid AS project_nid,
        usgr.field_usager_target_id AS uid,
        node.nid AS aur_nid,
        f.field_asset_usage_fee_value AS fee,
        note.field_note_value AS note
    FROM {node} node
    LEFT JOIN {field_data_field_asset_usage_fee} f ON node.nid = f.entity_id
    LEFT JOIN {field_data_field_usager} usgr ON node.nid = usgr.entity_id AND usgr.entity_type = 'node'
    LEFT JOIN {field_data_field_note} note ON node.nid = note.entity_id AND note.entity_type = 'node'
    LEFT JOIN {field_data_field__asset_owning_project} rp ON node.nid = rp.entity_id AND rp.entity_type = 'node'
    LEFT JOIN {node} nrp ON rp.field__asset_owning_project_target_id = nrp.nid
    WHERE node.status = 1
        AND node.type = 'asset_usage_record'
        AND node.nid > :lastnid
        AND nrp.nid IS NOT NULL
    ORDER BY nrp.nid, usgr.field_usager_target_id, node.nid
", array(':lastnid' => $last_aur_nid_orig));

// Group data by project and user to minimize processing
$projects_data = array();
$aur_nids_to_update = array();

foreach ($result as $row) {
    $project_nid = $row->project_nid;
    $uid = !empty($row->uid) ? $row->uid : 0;
    
    if (!isset($projects_data[$project_nid])) {
        $projects_data[$project_nid] = array();
    }
    if (!isset($projects_data[$project_nid][$uid])) {
        $projects_data[$project_nid][$uid] = array(
            'total_fee' => 0,
            'notes' => array()
        );
    }
    
    $projects_data[$project_nid][$uid]['total_fee'] += $row->fee;
    $projects_data[$project_nid][$uid]['notes'][] = $row->aur_nid;
    $aur_nids_to_update[] = $row->aur_nid;
}

// Process purchases for each project/user combination
foreach ($projects_data as $project_nid => $users_data) {
    foreach ($users_data as $uid => $user_data) {
        if ($user_data['total_fee'] > 0) {
            $user = user_load($uid);
            $note_links = array();
            foreach ($user_data['notes'] as $nid) {
                $note_links[] = l($nid, 'node/' . $nid);
            }
            $note = implode('; ', $note_links);
            
            rules_invoke_component('rules_process_purchase_core', $project_nid, $user_data['total_fee'], $user, $note);
        }
    }
}

// Bulk update processed flag
if (!empty($aur_nids_to_update)) {

    db_update('field_data_field_processed')
        ->fields(array('field_processed_value' => 1))
        ->condition('entity_type', 'node')
        ->condition('entity_id', $aur_nids_to_update, 'IN')
        ->execute();
    
    // Also update revision table if needed
    db_update('field_revision_field_processed')
        ->fields(array('field_processed_value' => 1))
        ->condition('entity_type', 'node')
        ->condition('entity_id', $aur_nids_to_update, 'IN')
        ->execute();
    
    // Update node changed timestamps to avoid Drupal caching issues
    db_update('node')
        ->fields(array('changed' => REQUEST_TIME))
        ->condition('nid', $aur_nids_to_update, 'IN')
        ->execute();
        
    // ---- Cache clearing logic ----

    // Reset node static cache
    entity_get_controller('node')->resetCache($aur_nids_to_update);

    // Clear field cache entries for updated nodes
    foreach ($aur_nids_to_update as $nid) {
        cache_clear_all('field:node:' . $nid, 'cache_field');
    }

    // If entitycache module is enabled, clear entity cache too
    if (module_exists('entitycache')) {
        foreach ($aur_nids_to_update as $nid) {
            cache_clear_all('node:' . $nid, 'cache_entity_node');
        }
    }
}
